<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_recommend_members( $user_id = 0, $limit = 6 ) { if ( ! class_exists( 'BP_Core_User' ) ) { return array(); } $user_id = absint( $user_id ?: get_current_user_id() ); $limit = min( 12, max( 1, absint( $limit ) ) ); $result = BP_Core_User::get( array( 'type' => 'active', 'per_page' => 50, 'page' => 1, 'exclude' => $user_id ) ); $users = ! empty( $result['users'] ) ? $result['users'] : array(); $ranked = array(); foreach ( $users as $user ) { $candidate_id = absint( $user->ID ); if ( ! $candidate_id || ( function_exists( 'sd_core_can_view_profile' ) && ! sd_core_can_view_profile( $candidate_id ) ) ) { continue; } $shared = function_exists( 'sd_core_shared_interest_count' ) ? sd_core_shared_interest_count( $user_id, $candidate_id ) : 0; $ranked[] = array( 'user' => $user, 'shared_interests' => $shared ); } usort( $ranked, function( $a, $b ) { if ( $a['shared_interests'] === $b['shared_interests'] ) { return strcasecmp( $a['user']->display_name, $b['user']->display_name ); } return $a['shared_interests'] < $b['shared_interests'] ? 1 : -1; } ); return array_slice( $ranked, 0, $limit ); }
